using AshkanSocialSphere.Domain;
using Microsoft.EntityFrameworkCore;
namespace AshkanSocialSphere.Infrastructure;
public sealed class SocialDbContext(DbContextOptions<SocialDbContext> options) : DbContext(options) {
 public DbSet<DirectMessage> DirectMessages=>Set<DirectMessage>(); public DbSet<SocialNotification> Notifications=>Set<SocialNotification>(); public DbSet<UserFollow> Follows => Set<UserFollow>(); public DbSet<SocialUser> Users => Set<SocialUser>(); public DbSet<SocialPost> Posts => Set<SocialPost>(); public DbSet<PostLike> Likes => Set<PostLike>(); public DbSet<PostComment> Comments => Set<PostComment>();
 protected override void OnModelCreating(ModelBuilder b) { b.Entity<DirectMessage>().HasIndex(x=>new{x.SenderId,x.RecipientId,x.CreatedUtc}); b.Entity<SocialNotification>().HasIndex(x=>new{x.UserId,x.CreatedUtc}); b.Entity<UserFollow>().HasKey(x=>new{x.FollowerId,x.FollowingId}); b.Entity<UserFollow>().HasOne<SocialUser>().WithMany().HasForeignKey(x=>x.FollowerId).OnDelete(DeleteBehavior.Restrict); b.Entity<UserFollow>().HasOne<SocialUser>().WithMany().HasForeignKey(x=>x.FollowingId).OnDelete(DeleteBehavior.Restrict); b.Entity<SocialUser>().HasIndex(x=>x.UserName).IsUnique(); b.Entity<SocialPost>().Property(x=>x.Content).HasMaxLength(2000); b.Entity<PostLike>().HasKey(x=>new{x.PostId,x.UserId}); b.Entity<PostLike>().HasOne<SocialPost>().WithMany(x=>x.Likes).HasForeignKey(x=>x.PostId).OnDelete(DeleteBehavior.Cascade); b.Entity<PostComment>().Property(x=>x.Content).HasMaxLength(500); b.Entity<PostComment>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId); b.Entity<PostComment>().HasIndex(x=>x.PostId); b.Entity<SocialPost>().HasOne(x=>x.Author).WithMany().HasForeignKey(x=>x.AuthorId).OnDelete(DeleteBehavior.Cascade); }
}
